// PbxServiceHandler is an implementation of the atsapbx.v1.PbxService service.
type PbxServiceHandler interface {
	// CreateExtension provisions an extension and makes it registrable by
	// a device. No apply step follows: it is live when this returns.
	CreateExtension(context.Context, *connect.Request[v1.CreateExtensionRequest]) (*connect.Response[v1.CreateExtensionResponse], error)
	// GetExtension reads one extension, including whether a device is
	// currently registered to it.
	GetExtension(context.Context, *connect.Request[v1.GetExtensionRequest]) (*connect.Response[v1.GetExtensionResponse], error)
	// ListExtensions returns a page of the calling tenant's extensions.
	ListExtensions(context.Context, *connect.Request[v1.ListExtensionsRequest]) (*connect.Response[v1.ListExtensionsResponse], error)
	// UpdateExtension changes an extension's display name or device type.
	// The number is immutable: renumbering would orphan every device
	// already provisioned against it, so it is a delete plus a create.
	UpdateExtension(context.Context, *connect.Request[v1.UpdateExtensionRequest]) (*connect.Response[v1.UpdateExtensionResponse], error)
	// DeleteExtension removes an extension and deprovisions it. A device
	// holding its former credential can no longer register, immediately.
	DeleteExtension(context.Context, *connect.Request[v1.DeleteExtensionRequest]) (*connect.Response[v1.DeleteExtensionResponse], error)
	// RegenerateSecret issues a new credential. The previous one stops
	// working the moment this returns — two live credentials for one
	// extension is the state a rotation exists to end.
	RegenerateSecret(context.Context, *connect.Request[v1.RegenerateSecretRequest]) (*connect.Response[v1.RegenerateSecretResponse], error)
	// GetSipRegistrar returns where devices register: the installation's
	// public SIP registrar address, as its installer configured it. When no
	// public host is configured it says so (configured = false) rather than
	// guess. Authorized like reading the tenant's extensions.
	GetSipRegistrar(context.Context, *connect.Request[v1.GetSipRegistrarRequest]) (*connect.Response[v1.GetSipRegistrarResponse], error)
	// CreateTrunk connects a partner-owned SIP carrier (BYOT). The carrier
	// secret, if any, is accepted here and on UpdateTrunk and is never
	// returned by any call — unlike an extension secret, it was chosen by
	// the carrier, not generated, so there is nothing to show once.
	CreateTrunk(context.Context, *connect.Request[v1.CreateTrunkRequest]) (*connect.Response[v1.CreateTrunkResponse], error)
	// ListTrunks returns a page of the calling tenant's trunks, with the
	// health the platform has observed for each.
	ListTrunks(context.Context, *connect.Request[v1.ListTrunksRequest]) (*connect.Response[v1.ListTrunksResponse], error)
	// UpdateTrunk replaces a trunk's configuration. An empty secret keeps
	// the stored one; an empty auth_username makes the trunk
	// IP-authenticated and discards any stored secret. Health is not an
	// input: it is observed, never set.
	UpdateTrunk(context.Context, *connect.Request[v1.UpdateTrunkRequest]) (*connect.Response[v1.UpdateTrunkResponse], error)
	// DeleteTrunk disconnects a carrier, together with every route that
	// sends to it. It is never selected again from the moment this
	// returns; calls already in progress are unaffected.
	DeleteTrunk(context.Context, *connect.Request[v1.DeleteTrunkRequest]) (*connect.Response[v1.DeleteTrunkResponse], error)
	// CreateRoute sends dialled numbers matching a prefix pattern to one of
	// the tenant's own trunks. Overlapping patterns are allowed: overlap is
	// how least-cost preference is expressed.
	CreateRoute(context.Context, *connect.Request[v1.CreateRouteRequest]) (*connect.Response[v1.CreateRouteResponse], error)
	// ListRoutes returns a page of the calling tenant's outbound routes.
	ListRoutes(context.Context, *connect.Request[v1.ListRoutesRequest]) (*connect.Response[v1.ListRoutesResponse], error)
	// DeleteRoute removes an outbound route.
	DeleteRoute(context.Context, *connect.Request[v1.DeleteRouteRequest]) (*connect.Response[v1.DeleteRouteResponse], error)
	// PlaceCall places a call from one of the tenant's extensions to a
	// destination as dialled. The platform's dial plan decides how it is
	// reached: an emergency number first, then another extension, then the
	// tenant's outbound routes. The caller's phone and the far end are rung
	// at the same time and connected when both answer. The request has no
	// field that names an engine endpoint or could exempt a call from
	// checks — only the dial plan recognises an emergency number.
	PlaceCall(context.Context, *connect.Request[v1.PlaceCallRequest]) (*connect.Response[v1.PlaceCallResponse], error)
	// HangupCall ends a call placed with PlaceCall. Ending a call that has
	// already ended succeeds and changes nothing.
	HangupCall(context.Context, *connect.Request[v1.HangupCallRequest]) (*connect.Response[v1.HangupCallResponse], error)
	// SetEmergencyProfile sets the tenant's emergency country (ISO 3166-1
	// alpha-2, upper case). Its catalogue numbers join 112 in the
	// effective emergency set from the next call on.
	SetEmergencyProfile(context.Context, *connect.Request[v1.SetEmergencyProfileRequest]) (*connect.Response[v1.SetEmergencyProfileResponse], error)
	// GetEmergencyProfile renders the tenant's effective emergency set:
	// 112, its country's catalogue numbers, and its own additions, each
	// marked built-in or own. It also reports whether a country is set and
	// whether it names a catalogued country.
	GetEmergencyProfile(context.Context, *connect.Request[v1.GetEmergencyProfileRequest]) (*connect.Response[v1.GetEmergencyProfileResponse], error)
	// CreateEmergencyNumber adds one of the tenant's own emergency
	// numbers. Numbers already effective (112, catalogue) cannot be added.
	CreateEmergencyNumber(context.Context, *connect.Request[v1.CreateEmergencyNumberRequest]) (*connect.Response[v1.CreateEmergencyNumberResponse], error)
	// ListEmergencyNumbers returns the tenant's effective emergency set.
	ListEmergencyNumbers(context.Context, *connect.Request[v1.ListEmergencyNumbersRequest]) (*connect.Response[v1.ListEmergencyNumbersResponse], error)
	// DeleteEmergencyNumber removes one of the tenant's own numbers. 112
	// and catalogue numbers are built-in and cannot be removed.
	DeleteEmergencyNumber(context.Context, *connect.Request[v1.DeleteEmergencyNumberRequest]) (*connect.Response[v1.DeleteEmergencyNumberResponse], error)
	// CreateInboundNumber assigns one of the tenant's inbound numbers
	// (DIDs) to one of its extensions. A carrier call to the number rings
	// that extension.
	CreateInboundNumber(context.Context, *connect.Request[v1.CreateInboundNumberRequest]) (*connect.Response[v1.CreateInboundNumberResponse], error)
	// ListInboundNumbers returns the tenant's inbound numbers.
	ListInboundNumbers(context.Context, *connect.Request[v1.ListInboundNumbersRequest]) (*connect.Response[v1.ListInboundNumbersResponse], error)
	// DeleteInboundNumber releases an inbound number. The extension keeps
	// working; only the public number stops ringing it.
	DeleteInboundNumber(context.Context, *connect.Request[v1.DeleteInboundNumberRequest]) (*connect.Response[v1.DeleteInboundNumberResponse], error)
}

